type View = WalkthroughView;
type Actor = DemoRole;
type ReviewDecision = 'accepted'|'rejected'|'edited';
const ErrorSchema = z.object({ error:z.string() });
const FilterTypeSchema = z.enum(['intended_use','claim','user_need','requirement','hazard','risk_control','component','test','clinical_evidence','label']);
const ACTIONS = ['review','update','retest','new_link','no_change'] as const;
const RELATIONSHIP_TYPES = ['REFINES','MITIGATES','IMPLEMENTS','VERIFIES','VALIDATES','SUPPORTED_BY','DISCLOSED_IN','DEPENDS_ON','MAY_AFFECT'] as const;

async function api<T>(url:string,schema:z.ZodType<T>,init?:RequestInit):Promise<T> {
  const response = await fetch(url,{ ...init,headers:{ 'content-type':'application/json',...(init?.headers ?? {}) } });
  const body:unknown = await response.json();
  if (!response.ok) { const parsed = ErrorSchema.safeParse(body); throw new Error(parsed.success ? parsed.data.error : `Request failed with status ${response.status}`); }
  return schema.parse(body);
}

function typeLabel(type:EvidenceType):string { return EVIDENCE_TYPE_LABELS[type]; }
function Loading() { return <div className="loading-state" role="status"><span className="loading-mark">BB</span><p>Preparing the evidence workspace…</p></div>; }
function StatusBadge({ value }:{ value:string }) { return <span className={`status-badge ${value.replaceAll('_','-')}`}>{value.replaceAll('_',' ')}</span>; }

function MetricCard({ id,label,value,caption,explanation,alert = false }:{ id:string;label:string;value:number;caption:string;explanation:string;alert?:boolean }) {
  const tooltipId = `metric-explanation-${id}`;
  return <article className={`metric-card${alert ? ' alert' : ''}`} tabIndex={0} aria-describedby={tooltipId}>
    <div className="metric-label"><p>{label}</p><span className="metric-help" aria-hidden="true">?</span></div>
    <strong>{value}</strong>
    <span className="metric-caption">{caption}</span>
    <span className="metric-tooltip" id={tooltipId} role="tooltip">{explanation}</span>
  </article>;
}

function InlineHelp({ id,explanation }:{ id:string;explanation:string }) {
  const tooltipId = `inline-explanation-${id}`;
  return <span className="inline-help" tabIndex={0} aria-describedby={tooltipId}>
    <span className="inline-help-mark" aria-hidden="true">?</span>
    <span className="inline-help-tooltip" id={tooltipId} role="tooltip">{explanation}</span>
  </span>;
}

function OverviewPanel({ overview,sources,onNavigate }:{ overview:OverviewView;sources:SourceListResponse;onNavigate:(view:View)=>void }) {
  return <section className="view-content">
    <div className="page-heading"><div><p className="eyebrow teal">Northstar Health · RhythmReview · {overview.baseline?.label ?? 'No baseline'}</p><h1>Product workspace</h1><p className="lede">Controlled product evidence shaped by source intent, implementation observations, human review, and immutable baselines.</p></div><button className="primary-button" onClick={() => onNavigate('sources')}>Process source material <span>→</span></button></div>
    <div className="notice" data-walkthrough="overview-boundary"><div className="notice-icon">i</div><p><b>Fictional evaluation dataset.</b> This workspace contains no patient, client, or submission data.</p></div>
    <div className="hero-flow"><button onClick={() => onNavigate('sources')}><span>01</span><b>Source material</b><small>{sources.sources.length} immutable revisions</small></button><i>→</i><button onClick={() => onNavigate('review')}><span>02</span><b>Review evidence</b><small>{sources.reviewCount} open records</small></button><i>→</i><button onClick={() => onNavigate('changes')}><span>03</span><b>Assess impact</b><small>Linked · semantic · collection</small></button><i>→</i><button onClick={() => onNavigate('baselines')}><span>04</span><b>Approve baseline</b><small>{sources.candidateBaselineReady ? 'Candidate ready' : 'Awaiting reviewed items'}</small></button></div>
    <div className="metric-grid" data-walkthrough="overview-metrics">
      <MetricCard id="evidence" label="Evidence items" value={overview.evidenceCount} caption="10 controlled types" explanation="Controlled evidence records in the active approved baseline, including intended use, claims, needs, requirements, risks, controls, designs, tests, clinical evidence, and labels." />
      <MetricCard id="relationships" label="Direct relationships" value={overview.relationshipCount} caption="In the active approved baseline" explanation="Explicitly stored source-to-target links between evidence items. This count does not include unlinked semantic candidates." />
      <MetricCard id="findings" label="Open coherence findings" value={overview.checkSummary.total} caption={`${overview.checkSummary.high} high severity`} explanation="Specific conditions shown for review. The total combines deterministic checks with seeded evaluation fixtures; it is not a composite health score." alert />
      <MetricCard id="documents" label="Document views" value={overview.documentCount} caption="Abbreviated evidence-grouped views" explanation="Abbreviated views assembled from exact evidence versions in a selected baseline. They are not submission-ready documents." />
    </div>
    <div className="dashboard-grid"><article className="panel evidence-health" data-walkthrough="overview-findings"><div className="panel-heading"><div><p className="eyebrow">Explainable checks</p><h2>Coherence findings <InlineHelp id="coherence-findings" explanation="Specific consistency conditions shown for reviewer attention. Each finding states its origin and can be traced to affected evidence." /></h2></div><button className="text-button" onClick={() => onNavigate('evidence')}>Browse evidence →</button></div><div className="health-summary check-counts"><div><strong>{overview.checkSummary.deterministic}</strong><span className="check-label">deterministic checks <InlineHelp id="deterministic-checks" explanation="Repeatable checks calculated from explicit rules and the stored baseline. They do not require AI judgment." /></span></div><div><strong>{overview.checkSummary.fixtures}</strong><span className="check-label">evaluation fixtures <InlineHelp id="evaluation-fixtures" explanation="Conditions deliberately seeded into the fictional dataset to exercise the review and evaluation workflow. They were not automatically detected." /></span></div><p>No composite health score is assigned.</p></div></article><article className="panel product-definition"><div className="panel-heading"><div><p className="eyebrow">Approved definition</p><h2>Intended use</h2></div><span className="tag">IU-001 · current baseline</span></div><blockquote>RhythmReview analyses a 30-second single-lead ECG recording to assist a qualified clinician in identifying possible atrial fibrillation in adults aged 22 and over.</blockquote><dl><div><dt>User</dt><dd>Qualified clinician</dd></div><div><dt>Decision role</dt><dd>Inform clinical review</dd></div><div><dt>Algorithm</dt><dd>Locked model</dd></div></dl></article></div>
  </section>;
}

function EvidencePanel({ evidence,selectedId,onSelect,initialType='all',title='Evidence browser',description='Inspect approved evidence versions and their direct relationships.' }:{ evidence:EvidenceItem[];selectedId:string|null;onSelect:(id:string)=>void;initialType?:'all'|EvidenceType;title?:string;description?:string }) {
  const [query,setQuery] = useState(''); const [type,setType] = useState<'all'|EvidenceType>(initialType); const [detail,setDetail] = useState<EvidenceDetailView|null>(null);
  const selected = selectedId ?? evidence[0]?.id ?? null;
  useEffect(() => { if (selected) void api(`/api/evidence/${selected}`,EvidenceDetailSchema).then(setDetail); },[selected]);
  const filtered = useMemo(() => evidence.filter((item) => (type === 'all' || item.type === type) && `${item.id} ${item.title} ${item.statement}`.toLowerCase().includes(query.toLowerCase())),[evidence,query,type]);
  const grouped = useMemo(() => detail ? {
    incoming:detail.relationships.filter((relation) => relation.targetId === detail.item.id),
    outgoing:detail.relationships.filter((relation) => relation.sourceId === detail.item.id),
  } : { incoming:[],outgoing:[] },[detail]);
  const relationshipList = (label:string,relationships:EvidenceDetailView['relationships']) => <div className="relation-group"><div className="subheading"><p className="eyebrow">{label}</p><span>{relationships.length}</span></div><div className="relation-list">{relationships.map((relation) => { const peer = relation.sourceId === detail?.item.id ? relation.targetId : relation.sourceId; return <button key={relation.id} onClick={() => onSelect(peer)}><span className="relation-flow"><code>{relation.sourceId}</code><b>— {relation.type.replaceAll('_',' ').toLowerCase()} →</b><code>{relation.targetId}</code></span><small>Open {peer}</small></button>; })}</div></div>;
  return <section className="view-content"><div className="page-heading compact"><div><p className="eyebrow teal">Active approved baseline</p><h1>{title}</h1><p className="lede">{description}</p></div><div className="count-chip">{filtered.length} of {evidence.length}</div></div><div className="browser-toolbar"><label><span className="sr-only">Search evidence</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search ID, title, or statement" /></label><label><span className="sr-only">Filter by type</span><select value={type} onChange={(event) => setType(event.target.value === 'all' ? 'all' : FilterTypeSchema.parse(event.target.value))}><option value="all">All evidence types</option>{Object.entries(EVIDENCE_TYPE_LABELS).map(([value,label]) => <option value={value} key={value}>{label}</option>)}</select></label></div><div className="evidence-layout"><div className="evidence-list" role="list">{filtered.map((item) => <button className={`evidence-list-item ${selected === item.id ? 'selected' : ''}`} key={item.id} onClick={() => onSelect(item.id)}><span><code>{item.id}</code><em>{typeLabel(item.type)}</em></span><b>{item.title}</b><small>{item.statement}</small><i className={`criticality ${item.criticality}`}>{item.criticality}</i></button>)}</div><article className="evidence-detail">{detail && detail.item.id === selected ? <><div className="detail-heading"><div><span className="type-pill">{typeLabel(detail.item.type)}</span><code>{detail.item.id} · v{detail.item.version}</code></div><StatusBadge value={detail.item.status} /></div><h2>{detail.item.title}</h2><p className="controlled-statement">{detail.item.statement}</p><div className="detail-meta"><div><span>Owner</span><b>{detail.item.owner}</b></div><div><span>Criticality</span><b>{detail.item.criticality}</b></div><div><span>Jurisdiction</span><b>{detail.item.jurisdictions.join(' + ')}</b></div></div><section><p className="eyebrow">Rationale</p><p>{detail.item.rationale}</p></section>{detail.item.flags.length > 0 && <section className="finding-box"><p className="eyebrow">Metadata and provenance</p>{detail.item.flags.map((flag) => <span key={flag}>{flag.replaceAll('_',' ')}</span>)}</section>}<section data-walkthrough="evidence-relationships"><div className="subheading"><div><p className="eyebrow">Relationships</p><small>Incoming and outgoing describe the saved source and target direction.</small></div><span>{detail.relationships.length} total</span></div>{relationshipList('Incoming relationships · this item is the target',grouped.incoming)}{relationshipList('Outgoing relationships · this item is the source',grouped.outgoing)}</section><section><p className="eyebrow">Source provenance</p>{detail.item.sources.map((source) => <div className="version-row" key={source}><span>source</span><b>{source}</b></div>)}</section><section><p className="eyebrow">Version history and baseline usage</p>{detail.versions.map((version) => <div className="version-row" key={version.versionId}><span>v{version.version}</span><b>{version.status}</b><small>{version.approvedBy ?? 'Not approved'}</small></div>)}</section></> : <Loading />}</article></div></section>;
}

function DocumentsPanel({ documents,refreshToken,onBaselineViewed }:{ documents:DocumentView[];refreshToken:string;onBaselineViewed:(label:string)=>void }) {
  const [selected,setSelected] = useState(documents[0]?.id ?? 'DOC-001'); const [baselineId,setBaselineId] = useState<string|null>(null); const [rendered,setRendered] = useState<RenderedDocumentView|null>(null); const [loadedKey,setLoadedKey] = useState<string|null>(null); const [loadError,setLoadError] = useState<string|null>(null);
  const requestKey = `${selected}|${baselineId ?? 'active'}|${refreshToken}`;
  const isLoading = loadedKey !== requestKey;
  useEffect(() => {
    let current = true;
    const query = baselineId ? `?baselineId=${encodeURIComponent(baselineId)}` : '';
    void api(`/api/documents/${selected}${query}`,RenderedDocumentSchema)
      .then((value) => {
        if (!current) return;
        setRendered(value);
        if (!baselineId) setBaselineId(value.baseline.id);
        setLoadedKey(requestKey);
        setLoadError(null);
        onBaselineViewed(value.baseline.label);
      })
      .catch((reason:unknown) => { if (current) { setLoadError(reason instanceof Error ? reason.message : 'Could not load the selected snapshot.');setLoadedKey(requestKey); } })
    return () => { current = false; };
  },[selected,baselineId,requestKey,onBaselineViewed]);
  const groups = useMemo(() => { const result = new Map<EvidenceType,EvidenceItem[]>(); for (const item of rendered?.items ?? []) result.set(item.type,[...(result.get(item.type) ?? []),item]); return [...result.entries()]; },[rendered]);
  const superseded = rendered?.items.filter((item) => item.status === 'superseded') ?? [];
  return <section className="view-content document-workspace"><div className="page-heading compact no-print"><div><p className="eyebrow teal">Immutable snapshots</p><h1>Controlled document views</h1><p className="lede">Each abbreviated view records the exact baseline and evidence versions used to render it.</p></div><div className="document-actions"><label data-walkthrough="document-baseline"><span>Approved baseline</span><select aria-label="Approved baseline" value={baselineId ?? ''} disabled={isLoading} onChange={(event) => { setLoadError(null);setBaselineId(event.target.value); }}>{rendered?.availableBaselines.map((baseline) => <option value={baseline.id} key={baseline.id}>{baseline.label} · {baseline.status}</option>)}</select></label><button className="secondary-button" disabled={isLoading} onClick={() => window.print()}>Print to PDF</button></div></div><div className="document-layout"><aside className="document-list no-print">{documents.map((document) => <button key={document.id} disabled={isLoading} className={selected === document.id ? 'selected' : ''} onClick={() => { setLoadError(null);setSelected(document.id); }}><span>{document.code}</span><b>{document.title}</b><small>{document.description}</small></button>)}</aside><article className="document-page" data-walkthrough="document-snapshot" aria-busy={isLoading}>{rendered ? <><header><p className="document-brand">BLUE BRIDGE · RHYTHMREVIEW</p><span>Controlled snapshot</span></header><div className="document-title"><p>{rendered.document.code} · {rendered.baseline.label}</p><h1>{rendered.document.title}</h1><p>{rendered.document.description}</p></div><div className="document-control"><div><span>Baseline status</span><b>{rendered.baseline.status}</b></div><div><span>Baseline</span><b>{rendered.baseline.label}</b></div><div><span>Approved by</span><b>{rendered.baseline.approvedBy ?? 'Not approved'}</b></div><div><span>Snapshot</span><b>{rendered.snapshotId}</b></div></div>{superseded.length > 0 && <div className="warning-banner">This snapshot includes superseded evidence: {superseded.map((item) => item.id).join(', ')}. The deterministic coherence check reports this condition.</div>}{groups.map(([groupType,items],index) => <section className="document-section" key={groupType}><p className="section-number">{String(index + 1).padStart(2,'0')}</p><div><h2>{typeLabel(groupType)}</h2>{items.map((item) => <article key={item.id}><div><code>{item.id} · v{item.version}</code><b>{item.title}</b></div><p>{item.statement}</p></article>)}</div></section>)}<footer>Fictional abbreviated document view · {rendered.items.length} source versions · snapshot created {new Date(rendered.renderedAt).toLocaleString()}</footer></> : <Loading />}{isLoading && rendered && <div className="document-loading" role="status">Loading the selected immutable snapshot…</div>}{loadError && <div className="error-banner" role="alert">{loadError}</div>}</article></div></section>;
}

function ControlledDocumentsPanel({ documents,refreshToken,onBaselineViewed,actor,baseline }:{ documents:DocumentView[];refreshToken:string;onBaselineViewed:(label:string)=>void;actor:Actor;baseline:{ id:string;label:string }|null }) {
  const [snapshot,setSnapshot]=useState<DocumentSnapshot|null>(null);const [documentPackage,setDocumentPackage]=useState<DocumentPackage|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState<string|null>(null);const [reason,setReason]=useState('QA verified the complete controlled package and manifest.');const first=documents[0];
  const command=async<T,>(url:string,schema:z.ZodType<T>,body:unknown):Promise<T|null>=>{setBusy(true);setError(null);try{return await api(url,schema,{method:'POST',body:JSON.stringify(body)});}catch(cause:unknown){setError(cause instanceof Error?cause.message:'Controlled document command failed.');return null;}finally{setBusy(false);}};
  const createSnapshot=async()=>{if(!baseline||!first)return;const result=await command('/api/document-snapshots',DocumentSnapshotSchema,{baselineId:baseline.id,templateVersionId:first.versionId,actor:demoActor(actor)});if(result)setSnapshot(result);};
  const buildPackage=async()=>{if(!baseline)return;const result=await command('/api/document-packages',DocumentPackageSchema,{baselineId:baseline.id,actor:demoActor(actor)});if(result)setDocumentPackage(result);};
  const decidePackage=async(decision:'accepted'|'rejected')=>{if(!documentPackage)return;const result=await command(`/api/document-packages/${documentPackage.id}/decision`,DocumentPackageSchema,{actor:demoActor(actor),decision,reason});if(result)setDocumentPackage(result);};
  return <><section className="view-content"><div className="page-heading compact"><div><p className="eyebrow teal">document-package-v1</p><h1>Controlled outputs</h1><p className="lede">Create immutable PDF and DOCX snapshots, then build the required ten-document package for separate QA acceptance.</p></div><span className="baseline-pill">{baseline?.label??'No approved baseline'}</span></div>{error&&<div className="error-banner">{error}</div>}<div className="source-metrics"><article><span>Template revisions</span><strong>{documents.length}</strong><small>current approved versions</small></article><article><span>Snapshot</span><strong>{snapshot?'Ready':'Preview'}</strong><small>{snapshot?.id??'not controlled'}</small></article><article><span>Package</span><strong>{documentPackage?.status.replaceAll('_',' ')??'Not built'}</strong><small>{documentPackage?.results.filter((result)=>result.status==='block').length??0} blocking results</small></article></div><div className="source-actions"><button disabled={busy||actor!=='author'||!baseline||!first} onClick={()=>void createSnapshot()}>Create {first?.code??'first'} snapshot</button><button className="primary-button" disabled={busy||actor!=='author'||!baseline} onClick={()=>void buildPackage()}>Build controlled package</button>{documentPackage?.status==='ready_for_qa'&&<><button disabled={busy||actor!=='qa'||reason.trim().length<2} onClick={()=>void decidePackage('rejected')}>Reject package</button><button className="approve-button" disabled={busy||actor!=='qa'||reason.trim().length<2} onClick={()=>void decidePackage('accepted')}>Accept package</button></>}</div>{documentPackage?.status==='ready_for_qa'&&<label><span>QA decision reason</span><textarea value={reason} onChange={(event)=>setReason(event.target.value)}/></label>}{snapshot&&<div className="version-row"><span>Snapshot files</span><b>{snapshot.files.map((file)=><a key={file.id} href={`/api/document-files/${file.id}`}>{file.format.toUpperCase()} · {file.filename}</a>)}</b><small>{snapshot.fingerprint}</small></div>}{documentPackage&&<section><p className="eyebrow">Package policy results</p>{documentPackage.results.map((result)=><div className="version-row" key={result.id}><span>{result.code}</span><b>{result.status} · {result.title}</b><small>{result.detail}</small></div>)}{documentPackage.status==='accepted'&&documentPackage.zipFile&&<a className="primary-button" href={`/api/document-files/${documentPackage.zipFile.id}`}>Download accepted ZIP</a>}</section>}</section><DocumentsPanel documents={documents} refreshToken={refreshToken} onBaselineViewed={onBaselineViewed}/></>;
}

function SuggestionCard({ suggestion,item,disabled,onDecision }:{ suggestion:ImpactSuggestion;item:EvidenceItem|undefined;disabled:boolean;onDecision:(id:string,decision:ReviewDecision,reason:string,editedAction?:typeof ACTIONS[number])=>void }) {
  const [editing,setEditing] = useState(false); const [decision,setDecision] = useState<ReviewDecision>('accepted'); const [editedAction,setEditedAction] = useState<typeof ACTIONS[number]>(suggestion.effectiveAction ?? suggestion.action); const [reason,setReason] = useState('');
  const submit = () => { if (reason.trim().length < 2) return; onDecision(suggestion.id,decision,reason,decision === 'edited' ? editedAction : undefined); setEditing(false); };
  const originLabel = suggestion.origin === 'linked' ? 'Confirmed graph path' : suggestion.origin === 'collection' ? 'Collection context' : 'Unlinked semantic candidate';
  return <article className={`suggestion ${suggestion.decision}`} data-walkthrough={`suggestion-${suggestion.targetId}`}>
    <div className="suggestion-top"><div><span className={`origin ${suggestion.origin}`}>{originLabel}</span></div><StatusBadge value={suggestion.effectiveAction ?? suggestion.action} /></div>
    <div className="suggestion-title"><code>{suggestion.targetId}</code><h3>{item?.title ?? suggestion.targetId}</h3></div><p>{suggestion.rationale}</p>
    {suggestion.origin === 'linked' ? <div className="path-strip"><span>Confirmed path</span>{suggestion.path.map((id,index) => <span key={`${id}-${index}`}><code>{id}</code>{index < suggestion.path.length - 1 && <b>→</b>}</span>)}</div> : <div className={`path-strip unlinked ${suggestion.origin}`}><span>{suggestion.origin === 'collection' ? 'Shared collection, not a direct trace link' : 'No direct relationship asserted'}</span><code>{suggestion.targetId}</code></div>}
    {suggestion.decision === 'edited' && <p className="decision-note">Original suggested action: <b>{suggestion.action}</b>. QA changed the controlled-scope action to <b>{suggestion.effectiveAction}</b>.</p>}{suggestion.decisionReason && <p className="decision-note">{suggestion.decidedBy}: {suggestion.decisionReason}</p>}
    <div className="suggestion-actions"><span>{suggestion.decision === 'pending' ? 'Awaiting QA decision' : `QA decision: ${suggestion.decision}`}</span><button disabled={disabled} onClick={() => { setDecision('rejected');setEditing(true); }}>{suggestion.decision === 'pending' ? 'Reject' : 'Revise decision'}</button><button className="accept" disabled={disabled} onClick={() => { setDecision('accepted');setEditing(true); }}>Accept</button><button disabled={disabled} onClick={() => { setDecision('edited');setEditing(true); }}>Edit action</button></div>
    {disabled && <small className="role-hint">Switch to QA reviewer to decide impact scope. Decisions close when drafting starts.</small>}
    {editing && <div className="decision-editor"><label><span>QA decision</span><select value={decision} onChange={(event) => setDecision(event.target.value as ReviewDecision)}><option value="accepted">Accept into change scope</option><option value="rejected">Reject from change scope</option><option value="edited">Accept with edited action</option></select></label>{decision === 'edited' && <label><span>Replacement action</span><select value={editedAction} onChange={(event) => setEditedAction(event.target.value as typeof ACTIONS[number])}>{ACTIONS.map((action) => <option key={action} value={action}>{action.replaceAll('_',' ')}</option>)}</select></label>}<label><span>Reason</span><textarea value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Record the evidence-based QA reason" /></label><div><button onClick={() => setEditing(false)}>Cancel</button><button className="accept" disabled={reason.trim().length < 2} onClick={submit}>Record decision</button></div></div>}
  </article>;
}

function DraftCard({ update,item,disabled,onUpdate }:{ update:ChangeView['updates'][number];item:EvidenceItem|undefined;disabled:boolean;onUpdate:(id:string,operation:'save'|'discard'|'restore',reason:string,text?:string)=>void }) {
  const [text,setText] = useState(update.proposedText); const [reason,setReason] = useState('');
  const historical = update.status === 'superseded' || update.status === 'approved';
  return <article className={update.status === 'discarded' || historical ? 'discarded' : ''} data-walkthrough={`draft-${update.itemId}`}>
    <div><code>{update.itemId} · candidate v{update.toVersion}</code><StatusBadge value={update.status} /></div>
    <h3>{item?.title}</h3>
    <p className="provenance-line">Original draft source: {update.draftOrigin.replaceAll('_',' ')}. Created by {update.createdBy}.</p>
    <div className="redline"><p><small>APPROVED BASELINE</small>{item?.statement}</p><p><small>ORIGINAL DRAFT, IMMUTABLE</small>{update.originalText}</p></div>
    <label className="draft-editor"><span>Author candidate text</span><textarea value={text} disabled={disabled || update.status !== 'proposed'} onChange={(event) => setText(event.target.value)} /></label>
    {update.editedBy && <p className="decision-note">Last changed by {update.editedBy}: {update.editReason}</p>}
    {!historical && <><label className="draft-reason"><span>Edit, discard, or restore reason</span><input value={reason} disabled={disabled} onChange={(event) => setReason(event.target.value)} placeholder="Required for every draft change" /></label><div className="draft-actions">{update.status === 'discarded' ? <button className="accept" disabled={disabled || reason.trim().length < 2} onClick={() => onUpdate(update.id,'restore',reason)}>Restore candidate version</button> : <><button disabled={disabled || reason.trim().length < 2} onClick={() => onUpdate(update.id,'discard',reason)}>Discard candidate version</button><button className="accept" disabled={disabled || reason.trim().length < 2 || text.trim().length < 8} onClick={() => onUpdate(update.id,'save',reason,text)}>Save author edit</button></>}</div></>}
    {disabled && !historical && <small className="role-hint">Switch to Author to manage candidate versions before QA submission.</small>}
  </article>;
}

function RelationshipProposalCard({ proposal,actor,disabled,onDecision,onUpdate }:{ proposal:ChangeView['relationshipProposals'][number];actor:Actor;disabled:boolean;onDecision:(id:string,decision:ReviewDecision,reason:string,editedType?:typeof RELATIONSHIP_TYPES[number])=>void;onUpdate:(proposal:ChangeView['relationshipProposals'][number],operation:'revise'|'discard'|'restore',reason:string,type?:typeof RELATIONSHIP_TYPES[number],rationale?:string)=>void }) {
  const [decision,setDecision] = useState<ReviewDecision>('accepted');
  const [editedType,setEditedType] = useState<typeof RELATIONSHIP_TYPES[number]>(proposal.effectiveType ?? proposal.proposedType ?? 'MAY_AFFECT');
  const [type,setType] = useState<typeof RELATIONSHIP_TYPES[number]>(proposal.proposedType ?? proposal.baseType ?? 'MAY_AFFECT');
  const [rationale,setRationale] = useState(proposal.rationale); const [reason,setReason] = useState('');
  const authorEditable = actor === 'author' && !disabled && (proposal.status === 'proposed' || proposal.status === 'discarded');
  const qaEditable = actor === 'qa' && !disabled && proposal.status === 'proposed';
  return <article className={`workflow-stage relationship-proposal ${proposal.status} ${proposal.decision?.decision ?? 'pending'}`}>
    <div className="section-heading"><div><p className="eyebrow">{proposal.operation} proposal · revision {proposal.revision}</p><h3><code>{proposal.sourceId}</code> → <code>{proposal.targetId}</code></h3></div><StatusBadge value={proposal.decision?.decision ?? proposal.status} /></div>
    <p><b>{proposal.operation === 'retire' ? proposal.baseType : proposal.effectiveType ?? proposal.proposedType}</b> · exact versions {proposal.sourceVersionId} and {proposal.targetVersionId}</p><p>{proposal.rationale}</p>{proposal.baseRelationshipId && <small>Predecessor relationship: {proposal.baseRelationshipId}</small>}
    {proposal.decision && <p className="decision-note">{proposal.decision.actor}: {proposal.decision.reason}{proposal.decision.decision === 'edited' ? ` Effective type: ${proposal.decision.editedType}.` : ''}</p>}
    {authorEditable && <div className="workflow-command"><label><span>Author rationale</span><input value={rationale} disabled={proposal.status === 'discarded'} onChange={(event) => setRationale(event.target.value)} /></label>{proposal.operation !== 'retire' && <label><span>Proposed type</span><select value={type} disabled={proposal.status === 'discarded'} onChange={(event) => setType(RelationshipTypeSchema.parse(event.target.value))}>{RELATIONSHIP_TYPES.map((value) => <option key={value}>{value}</option>)}</select></label>}<label><span>Reason for this revision</span><input value={reason} onChange={(event) => setReason(event.target.value)} /></label><div>{proposal.status === 'discarded' ? <button className="secondary-button" disabled={reason.trim().length < 2} onClick={() => onUpdate(proposal,'restore',reason)}>Restore</button> : <><button className="secondary-button" disabled={reason.trim().length < 2} onClick={() => onUpdate(proposal,'discard',reason)}>Discard</button>{proposal.operation !== 'retire' && <button className="primary-button" disabled={reason.trim().length < 2 || rationale.trim().length < 8} onClick={() => onUpdate(proposal,'revise',reason,type,rationale)}>Save revision</button>}</>}</div></div>}
    {qaEditable && <div className="workflow-command"><label><span>QA decision</span><select value={decision} onChange={(event) => setDecision(event.target.value as ReviewDecision)}><option value="accepted">Accept</option><option value="rejected">Reject</option>{proposal.operation !== 'retire' && <option value="edited">Accept with changed type</option>}</select></label>{decision === 'edited' && <label><span>Effective type</span><select value={editedType} onChange={(event) => setEditedType(RelationshipTypeSchema.parse(event.target.value))}>{RELATIONSHIP_TYPES.map((value) => <option key={value}>{value}</option>)}</select></label>}<label><span>QA reason</span><input value={reason} onChange={(event) => setReason(event.target.value)} /></label><button className="primary-button" disabled={reason.trim().length < 2} onClick={() => onDecision(proposal.id,decision,reason,decision === 'edited' ? editedType : undefined)}>Record QA decision</button><small>QA may change only the type. Endpoint changes require return to the author.</small></div>}
  </article>;
}

function VerificationPlanCandidateCard({ plan,disabled,onSave }:{ plan:ChangeView['verificationPlans'][number];disabled:boolean;onSave:(id:string,values:{ title:string;objective:string;method:string;acceptanceCriteria:string;rationale:string;reason:string })=>void }) {
  const [title,setTitle] = useState(plan.title); const [objective,setObjective] = useState(plan.objective); const [method,setMethod] = useState(plan.method); const [acceptanceCriteria,setAcceptanceCriteria] = useState(plan.acceptanceCriteria); const [rationale,setRationale] = useState(plan.rationale); const [reason,setReason] = useState('Clarified the fictional controlled verification plan.');
  const dirty = title !== plan.title || objective !== plan.objective || method !== plan.method || acceptanceCriteria !== plan.acceptanceCriteria || rationale !== plan.rationale;
  return <article className="verification-plan-card"><div className="verification-plan-heading"><div><code>{plan.proposedItemId} → {plan.targetRiskControlId}</code><h3>{plan.title}</h3></div><span className={`candidate-status ${plan.status}`}>{plan.status}</span></div><label><span>Title</span><input value={title} disabled={disabled} onChange={(event) => setTitle(event.target.value)} /></label><label><span>Objective</span><textarea value={objective} disabled={disabled} onChange={(event) => setObjective(event.target.value)} /></label><label><span>Method</span><textarea value={method} disabled={disabled} onChange={(event) => setMethod(event.target.value)} /></label><label><span>Acceptance criteria</span><textarea value={acceptanceCriteria} disabled={disabled} onChange={(event) => setAcceptanceCriteria(event.target.value)} /></label><label><span>Rationale</span><textarea value={rationale} disabled={disabled} onChange={(event) => setRationale(event.target.value)} /></label><label><span>Required edit reason</span><input value={reason} disabled={disabled} onChange={(event) => setReason(event.target.value)} /></label><button className="secondary-button" disabled={disabled || !dirty || reason.trim().length < 2} onClick={() => onSave(plan.id,{ title,objective,method,acceptanceCriteria,rationale,reason })}>Save plan revision</button><small>Revision {plan.revision}. Editing also revises the paired relationship proposal and makes earlier QA decisions stale.</small></article>;
}

function AddRelationshipProposal({ evidence,busy,onAdd,initialSourceId,initialTargetId }:{ evidence:EvidenceItem[];busy:boolean;onAdd:(draft:RelationshipProposalDraft)=>void;initialSourceId?:string;initialTargetId?:string }) {
  const [open,setOpen] = useState(Boolean(initialSourceId || initialTargetId)); const [sourceId,setSourceId] = useState(initialSourceId ?? ''); const [targetId,setTargetId] = useState(initialTargetId ?? '');
  const [type,setType] = useState<'' | typeof RELATIONSHIP_TYPES[number]>(''); const [rationale,setRationale] = useState('');
  if (!open) return <button className="secondary-button" onClick={() => setOpen(true)}>Add relationship proposal</button>;
  return <div className="workflow-command relationship-composer"><div className="browser-toolbar"><label><span>Source</span><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}><option value="">Choose source</option>{evidence.map((item) => <option key={item.id} value={item.id}>{item.id} · {item.title}</option>)}</select></label><label><span>Target</span><select value={targetId} onChange={(event) => setTargetId(event.target.value)}><option value="">Choose target</option>{evidence.map((item) => <option key={item.id} value={item.id}>{item.id} · {item.title}</option>)}</select></label></div><label><span>Relationship type</span><select value={type} onChange={(event) => setType(event.target.value === '' ? '' : RelationshipTypeSchema.parse(event.target.value))}><option value="">Choose type</option>{RELATIONSHIP_TYPES.map((value) => <option key={value}>{value}</option>)}</select></label><label><span>Statement-based rationale</span><textarea value={rationale} onChange={(event) => setRationale(event.target.value)} /></label><div><button className="text-button" onClick={() => setOpen(false)}>Cancel</button><button className="primary-button" disabled={busy || !sourceId || !targetId || !type || rationale.trim().length < 8} onClick={() => type && onAdd({ operation:'add',sourceId:EvidenceIdSchema.parse(sourceId),targetId:EvidenceIdSchema.parse(targetId),type,rationale })}>Add proposal</button></div><small>Compatible types are validated when saved; semantic adequacy still requires author rationale and QA review.</small></div>;
}


function ChangePanel({ overview,evidence,recentChanges,openChangeId,actor,selectedScenario,setSelectedScenario,onOpenChange,onWorkspaceRefresh,onOpenEvidence,onChangeState,onResetWorkspace,onAuditInspect }:{
  overview:OverviewView;
  evidence:EvidenceItem[];
  recentChanges:ChangeSummaryView[];
  openChangeId:string|null;
  actor:Actor;
  selectedScenario:ScenarioView|null;
  setSelectedScenario:(scenario:ScenarioView|null)=>void;
  onOpenChange:(change:ChangeSummaryView|null)=>void;
  onWorkspaceRefresh:()=>Promise<void>;
  onOpenEvidence:(itemId:string)=>void;
  onChangeState:(change:ChangeView|null)=>void;
  onResetWorkspace:()=>Promise<void>;
  onAuditInspect:()=>void;
}) {
  const [change,setChange] = useState<ChangeView|null>(null);
  const [mode,setMode] = useState<'replay'|'live'>('replay');
  const [busy,setBusy] = useState(false);
  const [error,setError] = useState<string|null>(null);
  const [returnReason,setReturnReason] = useState('');
  const [reopenReason,setReopenReason] = useState('');
  const [closeReason,setCloseReason] = useState('');
  const [candidateTraceability,setCandidateTraceability] = useState<CandidateTraceabilityView|null>(null);
  const itemById = useMemo(() => new Map(evidence.map((item) => [item.id,item])),[evidence]);
  const relationshipProjectionKey = change && change.relationshipProposals.length > 0 ? `${change.id}:${change.revision}` : null;

  useEffect(() => {
    if (!openChangeId) return;
    void api(`/api/changes/${openChangeId}`,ChangeViewSchema).then(setChange).catch((reason:unknown) => setError(reason instanceof Error ? reason.message : 'Could not open the stored change.'));
  },[openChangeId]);
  useEffect(() => { onChangeState(change); },[change,onChangeState]);
  useEffect(() => {
    if (!relationshipProjectionKey) return;
    const changeId = relationshipProjectionKey.split(':')[0];
    void api(`/api/changes/${changeId}/traceability`,CandidateTraceabilitySchema).then(setCandidateTraceability).catch((reason:unknown) => setError(reason instanceof Error ? reason.message : 'Could not load candidate traceability.'));
  },[relationshipProjectionKey]);

  const runAction = useCallback(async (action:()=>Promise<ChangeView>) => {
    setBusy(true); setError(null);
    try { const result = await action(); setChange(result); await onWorkspaceRefresh(); }
    catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'The action failed.'); }
    finally { setBusy(false); }
  },[onWorkspaceRefresh]);

  const create = () => {
    if (!selectedScenario) return;
    void runAction(async () => {
      const created = await api('/api/changes',ChangeViewSchema,{ method:'POST',body:JSON.stringify({ kind:'evidence',scenarioId:selectedScenario.id,anchorItemId:selectedScenario.anchorId,title:selectedScenario.title,proposedText:selectedScenario.proposedText,rationale:selectedScenario.rationale,createdBy:'Alex Morgan · Author' }) });
      return created;
    });
  };
  const analyse = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/analyse`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ mode }) })); };
  const reopen = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/reopen-analysis`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Alex Morgan · Author',mode,reason:reopenReason }) })); };
  const decide = (id:string,decision:ReviewDecision,reason:string,editedAction?:typeof ACTIONS[number]) => void runAction(() => api(`/api/suggestions/${id}/decision`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ decision,reason,editedAction,actor:'Jamie Chen · QA reviewer' }) }));
  const completeGuidedReview = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/guided-review-completion`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Jamie Chen · QA reviewer',confirmation:true }) })); };
  const draft = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/draft-updates`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Alex Morgan · Author' }) })); };
  const updateDraft = (id:string,operation:'save'|'discard'|'restore',reason:string,proposedText?:string) => void runAction(() => api(`/api/updates/${id}`,ChangeViewSchema,{ method:'PATCH',body:JSON.stringify({ operation,reason,proposedText,actor:'Alex Morgan · Author' }) }));
  const updateVerificationPlan = (id:string,values:{ title:string;objective:string;method:string;acceptanceCriteria:string;rationale:string;reason:string }) => void runAction(() => api(`/api/verification-plan-candidates/${id}`,ChangeViewSchema,{ method:'PATCH',body:JSON.stringify({ actor:'Alex Morgan · Author',...values }) }));
  const submit = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/submit`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Alex Morgan · Author' }) })); };
  const returnToAuthor = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/return-to-author`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Jamie Chen · QA reviewer',reason:returnReason }) })); };
  const addRelationship = (proposal:RelationshipProposalDraft) => { if (change) void runAction(() => api(`/api/changes/${change.id}/relationship-proposals`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Alex Morgan · Author',proposal }) })); };
  const decideRelationship = (id:string,decision:ReviewDecision,reason:string,editedType?:typeof RELATIONSHIP_TYPES[number]) => void runAction(() => api(`/api/relationship-proposals/${id}/decision`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Jamie Chen · QA reviewer',decision,reason,editedType }) }));
  const updateRelationship = (proposal:ChangeView['relationshipProposals'][number],operation:'revise'|'discard'|'restore',reason:string,type?:typeof RELATIONSHIP_TYPES[number],rationale?:string) => {
    const body = operation === 'discard' || operation === 'restore' ? { operation,actor:'Alex Morgan · Author',reason }
      : proposal.operation === 'add' ? { operation:'revise_add',actor:'Alex Morgan · Author',reason,sourceId:proposal.sourceId,targetId:proposal.targetId,type,rationale }
        : { operation:'revise_type',actor:'Alex Morgan · Author',reason,type,rationale };
    void runAction(() => api(`/api/relationship-proposals/${proposal.id}`,ChangeViewSchema,{ method:'PATCH',body:JSON.stringify(body) }));
  };
  const approve = async () => {
    if (!change) return;
    setBusy(true); setError(null);
    try { const result = await api(`/api/changes/${change.id}/approve`,ApprovalResponseSchema,{ method:'POST',body:JSON.stringify({ actor:'Jamie Chen · QA reviewer',confirmation:true }) }); setChange(result.change); await onWorkspaceRefresh(); }
    catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'Approval failed.'); }
    finally { setBusy(false); }
  };
  const closeWithoutBaseline = () => { if (change) void runAction(() => api(`/api/changes/${change.id}/close`,ChangeViewSchema,{ method:'POST',body:JSON.stringify({ actor:'Jamie Chen · QA reviewer',reason:closeReason,confirmation:true }) })); };
  const reset = async () => {
    setBusy(true); setError(null);
    try { await onResetWorkspace(); setChange(null); setSelectedScenario(null); onOpenChange(null); }
    catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'Reset failed.'); }
    finally { setBusy(false); }
  };
  const refreshChange = async () => { if (change) setChange(await api(`/api/changes/${change.id}`,ChangeViewSchema)); };
  const runCandidateCheck = async () => {
    if (!change) return;
    setBusy(true); setError(null);
    try { await api('/api/coherence-checks',CoherenceCheckSchema,{ method:'POST',body:JSON.stringify({ scope:{ kind:'candidate',changeId:change.id },actor:actor === 'qa' ? 'Jamie Chen · QA reviewer' : 'Alex Morgan · Author' }) }); await refreshChange(); await onWorkspaceRefresh(); }
    catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'Could not run candidate checks.'); }
    finally { setBusy(false); }
  };
  const disposition = async (finding:NonNullable<ChangeView['coherence']>['findings'][number],action:'waived'|'waiver_removed',reason:string) => {
    if (!change?.coherence) return;
    setBusy(true); setError(null);
    try { await api(`/api/coherence-findings/${encodeURIComponent(finding.id)}/dispositions`,CoherenceCheckSchema,{ method:'POST',body:JSON.stringify({ action,runId:change.coherence.id,fingerprint:finding.fingerprint,actor:'Jamie Chen · QA reviewer',reason }) }); await refreshChange(); await onWorkspaceRefresh(); }
    catch (cause:unknown) { setError(cause instanceof Error ? cause.message : 'Could not record the finding disposition.'); }
    finally { setBusy(false); }
  };
  const scrollTo = (id:string) => document.getElementById(id)?.scrollIntoView({ behavior:'smooth',block:'start' });

  if (openChangeId && !change) return <Loading />;
  if (!change && !selectedScenario) return <section className="view-content"><div className="page-heading compact"><div><p className="eyebrow teal">Customer compliance workflow</p><h1>Change workspace</h1><p className="lede">Reopen retained work or start a guided scenario. Approved baselines remain unchanged until separate QA approval.</p></div></div><RecentChanges changes={recentChanges} onOpen={(summary) => { setChange(null);onOpenChange(summary); }} /><div className="section-heading scenario-heading"><div><p className="eyebrow">Fictional demonstrations</p><h2>Guided scenarios</h2></div></div><div className="change-scenario-grid">{overview.scenarios.map((scenario) => <button data-walkthrough={scenario.id === 'SCN-002' ? 'scenario-timing' : undefined} onClick={() => { setChange(null);onOpenChange(null);setSelectedScenario(scenario); }} key={scenario.id}><span>{scenario.number}</span><p>{scenario.scale}</p><h2>{scenario.title}</h2><small>Starts from {scenario.anchorId}</small><b>Open scenario →</b></button>)}</div></section>;

  const anchorId = change?.anchorItemId ?? selectedScenario?.anchorId;
  const anchor = anchorId ? itemById.get(anchorId) : null;
  const currentUpdates = change?.updates.filter((update) => update.status !== 'superseded' && (!change.run || update.analysisRunId === '' || update.analysisRunId === change.run.id)) ?? [];
  const historicalUpdates = change?.updates.filter((update) => update.status === 'superseded') ?? [];
  const activeUpdates = currentUpdates.filter((update) => update.status === 'proposed');
  const allDecided = Boolean(change?.run) && Boolean(change?.suggestions.every((suggestion) => suggestion.decision !== 'pending'));
  const actionableAccepted = change?.suggestions.some((suggestion) => (suggestion.decision === 'accepted' || suggestion.decision === 'edited') && (suggestion.effectiveAction === 'update' || suggestion.effectiveAction === 'retest')) ?? false;
  const canReopen = change ? ['ready_for_review','under_review','updates_proposed','returned_to_author'].includes(change.status) : false;
  const canAuthorRelationships = change ? ['ready_for_review','under_review','updates_proposed','returned_to_author'].includes(change.status) : false;
  const acceptedNewLink = change?.suggestions.find((suggestion) => (suggestion.decision === 'accepted' || suggestion.decision === 'edited') && suggestion.effectiveAction === 'new_link' && !change.relationshipProposals.some((proposal) => proposal.status !== 'superseded' && (proposal.sourceId === suggestion.targetId || proposal.targetId === suggestion.targetId)));
  const allActiveRelationshipDecisions = change?.relationshipProposals.filter((proposal) => proposal.status === 'proposed').every((proposal) => proposal.decision) ?? true;
  const req004 = change?.suggestions.find((suggestion) => suggestion.targetId === 'REQ-004');
  const test007 = change?.suggestions.find((suggestion) => suggestion.targetId === 'TEST-007');
  const un004 = change?.suggestions.find((suggestion) => suggestion.targetId === 'UN-004');
  const guidedManualExamplesComplete = change?.scenarioId === 'SCN-002' && change.run?.mode === 'replay'
    && req004?.decision === 'accepted'
    && test007?.decision === 'accepted'
    && change.audit.some((event) => event.entityId === test007.id && event.action === 'suggestion_rejected')
    && un004?.decision === 'edited'
    && un004.effectiveAction === 'update';
  const guidedPendingCount = change?.suggestions.filter((suggestion) => suggestion.decision === 'pending').length ?? 0;
  const proposalText = change?.proposedText ?? selectedScenario?.proposedText ?? '';
  const rationale = change?.rationale ?? selectedScenario?.rationale ?? '';
  const title = change?.title ?? selectedScenario?.title ?? 'Controlled change';
  const scenarioLabel = selectedScenario ? `Scenario ${selectedScenario.number} · ${selectedScenario.scale}` : 'Stored controlled change';

  if (change?.subjectKind === 'verification_package') {
    const authorOpen = change.status === 'updates_proposed' || change.status === 'returned_to_author';
    const activeRelationships = change.relationshipProposals.filter((proposal) => proposal.status === 'proposed');
    const allRelationshipDecided = activeRelationships.length === change.verificationPlans.length && activeRelationships.every((proposal) => proposal.decision);
    return <section className="view-content verification-package-workspace"><div className="page-heading compact"><div><p className="eyebrow teal">Controlled verification package</p><h1>{change.title}</h1><p className="lede">Two controlled risk-control amendments and three TEST plans move together through revision-bound relationship review.</p></div><button className="secondary-button" onClick={() => { setChange(null);setSelectedScenario(null);onOpenChange(null); }}>All changes</button></div>{error && <div className="error-banner" role="alert">{error}</div>}
      <div className="notice"><div className="notice-icon">i</div><p><b>Base baseline {change.baseBaselineId} remains immutable.</b> Only a plan with a currently accepted paired VERIFIES proposal enters the new baseline.</p></div>
      <div className="change-stepper"><button className="done">1 · Package</button><button className={change.status === 'qa_review' || change.status === 'approved' ? 'done' : 'current'}>2 · Submit</button><button className={allRelationshipDecided ? 'done' : change.status === 'qa_review' ? 'current' : ''}>3 · Link review</button><button className={candidateTraceability?.valid ? 'done' : ''}>4 · Projection</button><button className={change.status === 'approved' ? 'done' : change.status === 'qa_review' ? 'current' : ''}>5 · Baseline</button></div>
      <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Risk-control wording</p><h2>Normal proposed evidence updates</h2></div><StatusBadge value={change.status} /></div>{currentUpdates.map((update) => <DraftCard key={update.id} update={update} item={itemById.get(update.itemId)} disabled={actor !== 'author' || busy || !authorOpen} onUpdate={updateDraft} />)}</section>
      <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Structured TEST candidates</p><h2>Plan identity remains the TEST evidence version</h2></div><span>{change.verificationPlans.length} plans</span></div><div className="verification-plan-grid">{change.verificationPlans.map((plan) => <VerificationPlanCandidateCard key={`${plan.id}-${plan.revision}`} plan={plan} disabled={actor !== 'author' || busy || !authorOpen} onSave={updateVerificationPlan} />)}</div></section>
      <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Paired controlled traceability</p><h2>One VERIFIES proposal per TEST plan</h2></div><span>{activeRelationships.filter((proposal) => proposal.decision?.decision === 'accepted' || proposal.decision?.decision === 'edited').length} accepted</span></div>{change.relationshipProposals.map((proposal) => <RelationshipProposalCard key={`${proposal.id}-${proposal.revision}-${proposal.decision?.createdAt ?? ''}`} proposal={proposal} actor={actor} disabled={busy || (authorOpen ? true : change.status !== 'qa_review')} onDecision={decideRelationship} onUpdate={updateRelationship} />)}{authorOpen && <button className="primary-button" disabled={actor !== 'author' || busy || activeUpdates.length !== 2 || change.verificationPlans.length !== 3} onClick={submit}>Submit complete package to QA →</button>}</section>
      {candidateTraceability && <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Deterministic candidate projection</p><h2>Coverage before baseline approval</h2></div><span className={candidateTraceability.valid ? 'tag' : 'status-badge rejected'}>{candidateTraceability.valid ? 'Policy valid' : 'Blocked by policy'}</span></div><div className="trace-summary"><article><span>Base evidence</span><strong>{candidateTraceability.base.summary.evidenceItems}</strong></article><article><span>Projected evidence</span><strong>{candidateTraceability.projected.summary.evidenceItems}</strong></article><article><span>Base links</span><strong>{candidateTraceability.base.summary.activeLinks}</strong></article><article><span>Projected links</span><strong>{candidateTraceability.projected.summary.activeLinks}</strong></article><article><span>High gaps before</span><strong>{candidateTraceability.base.summary.highCoverageGaps}</strong></article><article><span>High gaps after</span><strong>{candidateTraceability.projected.summary.highCoverageGaps}</strong></article></div></section>}
      <CoherenceWorkspace title="Projected verification-package findings" check={change.coherence} actor={actor} busy={busy} onRun={() => void runCandidateCheck()} onDisposition={(finding,action,reason) => void disposition(finding,action,reason)} onOpenEvidence={onOpenEvidence} />
      {change.status === 'qa_review' && <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Separate QA baseline decision</p><h2>Candidate package awaiting QA</h2></div><StatusBadge value={change.status} /></div><div className="approval-actions"><div className="workflow-command"><label><span>Reason to return to author</span><input value={returnReason} disabled={actor !== 'qa' || busy} onChange={(event) => setReturnReason(event.target.value)} /></label><button className="secondary-button" disabled={actor !== 'qa' || busy || returnReason.trim().length < 2} onClick={returnToAuthor}>Return to author</button></div><button className="approve-button" disabled={actor !== 'qa' || busy || !allRelationshipDecided || !candidateTraceability?.valid || change.coherence?.stale === true} onClick={() => void approve()}>Approve new immutable baseline</button></div>{actor !== 'qa' && <small className="role-hint">Switch to QA reviewer to decide links and approve the baseline.</small>}</section>}
      {change.status === 'approved' && <section className="workflow-stage"><div className="approval-complete"><span>✓</span><div><h3>Verification package approved</h3><p>Accepted plans and links entered the new baseline. Rejected candidates remain only in change history.</p></div></div></section>}
      <AuditHistory events={change.audit} onInspect={onAuditInspect} />
    </section>;
  }

  if (change?.subjectKind === 'relationship') {
    const activeRelationships = change.relationshipProposals.filter((proposal) => proposal.status === 'proposed');
    const allRelationshipDecided = activeRelationships.length > 0 && activeRelationships.every((proposal) => proposal.decision);
    const allRelationshipRejected = allRelationshipDecided && activeRelationships.every((proposal) => proposal.decision?.decision === 'rejected');
    const authorOpen = change.status === 'updates_proposed' || change.status === 'returned_to_author';
    return <section className="view-content relationship-change-workspace"><div className="page-heading compact"><div><p className="eyebrow teal">Five-minute controlled traceability flow</p><h1>{change.title}</h1><p className="lede">Relationship-only changes use a deterministic candidate projection and never call OpenRouter.</p></div><button className="secondary-button" onClick={() => { setChange(null);setSelectedScenario(null);onOpenChange(null); }}>All changes</button></div>{error && <div className="error-banner" role="alert">{error}</div>}
      <div className="notice"><div className="notice-icon">i</div><p><b>Base baseline {change.baseBaselineId} remains immutable.</b> Approval copies unchanged links into a new baseline, applies accepted proposals, and preserves every revision and QA decision.</p></div>
      <div className="change-stepper"><button className="done">1 · Propose</button><button className={change.status === 'qa_review' || change.status === 'approved' ? 'done' : 'current'}>2 · Submit</button><button className={allRelationshipDecided ? 'done' : change.status === 'qa_review' ? 'current' : ''}>3 · QA decision</button><button className={candidateTraceability ? 'done' : ''}>4 · Projection</button><button className={change.status === 'approved' || change.status === 'closed' ? 'done' : change.status === 'qa_review' ? 'current' : ''}>5 · Baseline outcome</button></div>
      <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Relationship proposals</p><h2>{change.id} · revision {change.revision}</h2></div><StatusBadge value={change.status} /></div>{change.relationshipProposals.map((proposal) => <RelationshipProposalCard key={`${proposal.id}-${proposal.revision}-${proposal.decision?.createdAt ?? ''}`} proposal={proposal} actor={actor} disabled={busy || !authorOpen && change.status !== 'qa_review'} onDecision={decideRelationship} onUpdate={updateRelationship} />)}{authorOpen && actor === 'author' && <AddRelationshipProposal evidence={evidence} busy={busy} onAdd={addRelationship} />}{authorOpen && <button className="primary-button" data-walkthrough="submit-candidates" disabled={actor !== 'author' || busy || activeRelationships.length === 0} onClick={submit}>Submit relationship proposals to QA →</button>}</section>
      {candidateTraceability && <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Deterministic candidate projection</p><h2>Matrix and coverage before approval</h2></div><span className={candidateTraceability.valid ? 'tag' : 'status-badge rejected'}>{candidateTraceability.valid ? 'Policy valid' : 'Blocked by policy'}</span></div><div className="trace-summary"><article><span>Base links</span><strong>{candidateTraceability.base.summary.activeLinks}</strong><small>{candidateTraceability.base.baseline.label}</small></article><article><span>Projected links</span><strong>{candidateTraceability.projected.summary.activeLinks}</strong><small>candidate only</small></article><article><span>Coverage gaps before</span><strong>{candidateTraceability.base.summary.coverageGaps}</strong><small>{candidateTraceability.base.summary.highCoverageGaps} high</small></article><article><span>Coverage gaps after</span><strong>{candidateTraceability.projected.summary.coverageGaps}</strong><small>{candidateTraceability.projected.summary.highCoverageGaps} high; gaps do not gate WP-10A</small></article></div><div className="trace-rule-register"><div>{candidateTraceability.deltas.map((delta) => <article key={delta.proposalId}><code>{delta.operation} · {delta.status}</code><b>{delta.relationship ? `${delta.relationship.sourceId} ${delta.relationship.type} ${delta.relationship.targetId}` : 'No effective candidate link'}</b><p>{delta.error ?? 'Included in the current projection.'}</p></article>)}</div></div></section>}
      {change.status === 'qa_review' && <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Separate QA baseline decision</p><h2>Choose the controlled outcome</h2></div><StatusBadge value={change.status} /></div><div className="approval-actions"><div className="workflow-command"><label><span>Reason to return to author</span><input value={returnReason} onChange={(event) => setReturnReason(event.target.value)} /></label><button className="secondary-button" disabled={actor !== 'qa' || busy || returnReason.trim().length < 2} onClick={returnToAuthor}>Return for endpoint or rationale changes</button></div>{allRelationshipRejected ? <div className="workflow-command"><label><span>Reason to close without a baseline</span><input value={closeReason} onChange={(event) => setCloseReason(event.target.value)} /></label><button className="secondary-button" disabled={actor !== 'qa' || busy || closeReason.trim().length < 2} onClick={closeWithoutBaseline}>Close without creating a baseline</button></div> : <button className="approve-button" disabled={actor !== 'qa' || busy || !allRelationshipDecided || !candidateTraceability?.valid} onClick={() => void approve()}>Approve new immutable baseline</button>}</div></section>}
      {(change.status === 'approved' || change.status === 'closed') && <section className="workflow-stage"><div className="approval-complete"><span>✓</span><div><h3>{change.status === 'approved' ? 'New baseline approved' : 'Change closed without a baseline'}</h3><p>{change.status === 'approved' ? 'The relationship appears only in the new baseline; the previous relationship set remains unchanged.' : 'All proposals were rejected, so the active baseline was not changed.'}</p></div></div></section>}
      <AuditHistory events={change.audit} onInspect={onAuditInspect} /><div className="demo-controls"><p><b>Walkthrough check</b>After approval, confirm the new link in Matrix and verify the unrelated RC-005 gap remains open in Coverage.</p><button data-walkthrough="reset-workspace" disabled={busy} onClick={() => void reset()}>Reset workspace</button></div>
    </section>;
  }

  return <section className="view-content"><div className="page-heading compact"><div><p className="eyebrow teal">{scenarioLabel}</p><h1>{title}</h1><p className="lede">{rationale}</p></div><button className="secondary-button" onClick={() => { setChange(null);setSelectedScenario(null);onOpenChange(null); }}>All changes</button></div>{error && <div className="error-banner" role="alert">{error}</div>}
    <div className="change-stepper"><button className={change ? 'done' : 'current'} onClick={() => scrollTo('stage-proposal')}>1 · Proposal</button><button className={change?.run ? 'done' : change ? 'current' : ''} disabled={!change} onClick={() => scrollTo('stage-analysis')}>2 · Analysis</button><button className={allDecided ? 'done' : change?.run ? 'current' : ''} disabled={!change?.run} onClick={() => scrollTo('stage-review')}>3 · Scope review</button><button className={currentUpdates.length ? 'done' : ''} disabled={!currentUpdates.length} onClick={() => scrollTo('stage-draft')}>4 · Candidate drafts</button><button className={change?.status === 'approved' ? 'done' : change?.status === 'qa_review' ? 'current' : ''} disabled={change?.status !== 'qa_review' && change?.status !== 'approved'} onClick={() => scrollTo('stage-approval')}>5 · QA approval</button></div>
    <section id="stage-proposal" className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Controlled proposal</p><h2>{change?.id ?? 'Not yet created'}</h2></div>{change && <StatusBadge value={change.status} />}</div><div className="change-proposal"><article><p className="eyebrow">Current approved evidence</p><div className="change-item-heading"><code>{anchor?.id}</code><h2>{anchor?.title}</h2></div><p>{anchor?.statement}</p></article><div className="change-arrow">→</div><article className="proposed"><p className="eyebrow">Human-authored proposal fixture</p><div className="change-item-heading"><code>{anchorId}</code><h2>Candidate wording</h2></div><p>{proposalText}</p></article><div className="proposal-rationale"><span>Rationale</span><p>{rationale}</p></div>{!change && <><button className="primary-button" data-walkthrough="create-change" disabled={actor !== 'author' || busy} onClick={create}>{busy ? 'Creating…' : 'Create controlled change'}</button>{actor !== 'author' && <small className="role-hint">Switch to Author to create the change.</small>}</>}</div></section>
    {change && <section id="stage-analysis" className="workflow-stage analysis-launch"><div className="section-heading"><div><p className="eyebrow">Impact analysis</p><h2>{change.run ? 'Current analysis run' : 'Choose an analysis mode'}</h2></div>{change.run && <span className="tag">{change.analysisHistory.length} retained run{change.analysisHistory.length === 1 ? '' : 's'}</span>}</div><p>Deterministic relationship traversal supplies graph candidates. Replay loads a locked fixture. Live mode sends only supplied fictional candidates through OpenRouter.</p><div className="mode-switch"><button className={mode === 'replay' ? 'active' : ''} onClick={() => setMode('replay')}><b>Replay fixture</b><span>Saved output, no API key</span></button><button className={mode === 'live' ? 'active' : ''} onClick={() => setMode('live')}><b>Live OpenRouter</b><span>Requires a configured OpenRouter key</span></button></div>{!change.run && <button className="primary-button" data-walkthrough="load-replay" disabled={actor !== 'author' || busy || change.status !== 'draft'} onClick={analyse}>{busy ? 'Analysing…' : mode === 'replay' ? 'Load replay fixture' : 'Run live AI analysis'}</button>}{change.run && <p>{change.run.mode === 'replay' ? 'Locked replay fixture' : 'Live OpenRouter output'} · {change.run.model} · {change.run.promptVersion}</p>}{canReopen && <div className="workflow-command"><label><span>Reason to supersede the current analysis</span><input value={reopenReason} disabled={actor !== 'author' || busy} onChange={(event) => setReopenReason(event.target.value)} /></label><button className="secondary-button" disabled={actor !== 'author' || busy || reopenReason.trim().length < 2} onClick={reopen}>Reopen analysis</button><small>A successful run supersedes current decisions and drafts. A failed run restores them.</small></div>}{change.analysisHistory.filter((run) => run.status === 'failed').map((run) => <div className="warning-banner" key={run.id}>Failed {run.mode} run: {run.error}</div>)}</section>}
    {change?.analysisWarning && <div className="warning-banner">{change.analysisWarning}</div>}
    {change?.run && <section id="stage-review" className="workflow-stage" data-walkthrough="suggestion-review"><div className="review-summary"><div><p className="eyebrow">Impact suggestions, not evidence updates</p><h2>{change.suggestions.length} suggestions for QA classification</h2><p>Accepting a suggestion adds an item and action to the controlled change scope. It does not edit or approve evidence.</p></div><div><span><b>{change.suggestions.filter((item) => item.origin === 'semantic').length}</b> unlinked candidates</span><span><b>{change.suggestions.filter((item) => item.decision !== 'pending').length}</b> reviewed</span></div></div><div className="suggestion-list">{change.suggestions.map((suggestion) => <SuggestionCard key={suggestion.id} suggestion={suggestion} item={itemById.get(suggestion.targetId)} disabled={actor !== 'qa' || busy || (change.status !== 'ready_for_review' && change.status !== 'under_review')} onDecision={decide} />)}</div>{guidedManualExamplesComplete && guidedPendingCount > 0 && <div className="guided-completion" data-walkthrough="guided-completion"><div><p className="eyebrow">Guided replay helper</p><h3>Complete {guidedPendingCount} remaining saved decisions</h3><p>This records labelled fixture decisions after the presenter has demonstrated accept, reject and revise, and edit action. Each decision remains visible in the audit history.</p></div><button className="secondary-button" disabled={actor !== 'qa' || busy} onClick={completeGuidedReview}>{busy ? 'Recording…' : 'Apply remaining fixture decisions'}</button></div>}{allDecided && actionableAccepted && currentUpdates.length === 0 && <div className="next-action"><div><p className="eyebrow">Author action</p><h2>Create candidate draft versions</h2><p>Replay drafting uses labelled fixture text. The original draft remains available after human edits.</p></div><button className="primary-button" data-walkthrough="create-drafts" disabled={actor !== 'author' || busy} onClick={draft}>Create candidate drafts →</button></div>}{!allDecided && <p className="gate-note">QA must decide every current suggestion before the author can draft candidate versions.</p>}</section>}
    {change && currentUpdates.length > 0 && <section id="stage-draft" className="workflow-stage update-review"><div className="section-heading"><div><p className="eyebrow">Candidate versions, not approved evidence</p><h2>{activeUpdates.length} retained · {currentUpdates.filter((update) => update.status === 'discarded').length} discarded</h2></div><StatusBadge value={change.status} /></div>{currentUpdates.map((update) => <DraftCard key={update.id} update={update} item={itemById.get(update.itemId)} disabled={actor !== 'author' || busy || (change.status !== 'updates_proposed' && change.status !== 'returned_to_author')} onUpdate={updateDraft} />)}{(change.status === 'updates_proposed' || change.status === 'returned_to_author') && <button className="primary-button" data-walkthrough="submit-candidates" disabled={actor !== 'author' || busy || activeUpdates.length === 0} onClick={submit}>Send retained candidate versions to QA →</button>}</section>}
    {historicalUpdates.length > 0 && <details className="workflow-stage historical-drafts"><summary>{historicalUpdates.length} superseded candidate draft{historicalUpdates.length === 1 ? '' : 's'}</summary>{historicalUpdates.map((update) => <DraftCard key={update.id} update={update} item={itemById.get(update.itemId)} disabled onUpdate={updateDraft} />)}</details>}
    {change && (change.relationshipProposals.length > 0 || canAuthorRelationships) && <section className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Controlled traceability changes</p><h2>Relationship proposals</h2></div><span>{change.relationshipProposals.filter((proposal) => proposal.status === 'proposed').length} active</span></div>{acceptedNewLink && <div className="notice"><div className="notice-icon">i</div><p><b>Accepted new-link suggestion.</b> The composer is prefilled with relevant evidence, but it will not select a relationship type or assert semantic adequacy.</p></div>}{change.relationshipProposals.map((proposal) => <RelationshipProposalCard key={`${proposal.id}-${proposal.revision}-${proposal.decision?.createdAt ?? ''}`} proposal={proposal} actor={actor} disabled={busy || !canAuthorRelationships && change.status !== 'qa_review'} onDecision={decideRelationship} onUpdate={updateRelationship} />)}{canAuthorRelationships && actor === 'author' && <AddRelationshipProposal evidence={evidence} busy={busy} onAdd={addRelationship} initialSourceId={acceptedNewLink ? change.anchorItemId : undefined} initialTargetId={acceptedNewLink?.targetId} />}{(change.status === 'updates_proposed' || change.status === 'returned_to_author') && activeUpdates.length === 0 && change.relationshipProposals.some((proposal) => proposal.status === 'proposed') && <button className="primary-button" disabled={actor !== 'author' || busy} onClick={submit}>Submit retained relationship proposals to QA →</button>}{candidateTraceability && <div className="trace-summary"><article><span>Base links</span><strong>{candidateTraceability.base.summary.activeLinks}</strong></article><article><span>Projected links</span><strong>{candidateTraceability.projected.summary.activeLinks}</strong></article><article><span>Gaps before</span><strong>{candidateTraceability.base.summary.coverageGaps}</strong></article><article><span>Gaps after</span><strong>{candidateTraceability.projected.summary.coverageGaps}</strong></article></div>}</section>}
    {change && <CoherenceWorkspace title="Projected candidate findings" check={change.coherence} actor={actor} busy={busy} onRun={() => void runCandidateCheck()} onDisposition={(finding,action,reason) => void disposition(finding,action,reason)} onOpenEvidence={onOpenEvidence} />}
    {change?.status === 'qa_review' && <section id="stage-approval" className="workflow-stage"><div className="section-heading"><div><p className="eyebrow">Separate QA baseline decision</p><h2>Candidate baseline awaiting QA</h2></div><StatusBadge value={change.status} /></div><p>The active approved baseline remains unchanged. Returning the candidate preserves the current analysis, decisions, drafts, and relationship proposal history.</p><div className="approval-actions"><div className="workflow-command"><label><span>Reason to return to author</span><input value={returnReason} disabled={actor !== 'qa' || busy} onChange={(event) => setReturnReason(event.target.value)} /></label><button className="secondary-button" disabled={actor !== 'qa' || busy || returnReason.trim().length < 2} onClick={returnToAuthor}>Return to author</button></div><button className="approve-button" data-walkthrough="approve-baseline" disabled={actor !== 'qa' || busy || !allActiveRelationshipDecisions || candidateTraceability?.valid === false} onClick={() => void approve()}>Approve new immutable baseline</button></div>{!allActiveRelationshipDecisions && <small className="role-hint">QA must decide every current relationship proposal revision before approval.</small>}{actor !== 'qa' && <small className="role-hint">Switch to QA reviewer to return or approve the candidate. The author cannot do either.</small>}</section>}
    {change?.status === 'approved' && <section id="stage-approval" className="workflow-stage" data-walkthrough="approval-complete"><div className="approval-complete"><span>✓</span><div><h3>New baseline approved</h3><p>This stored change is read-only. The prior baseline and every superseded analysis remain available.</p></div></div></section>}
    {change && <AuditHistory events={change.audit} onInspect={onAuditInspect} />}
    <div className="demo-controls"><p><b>Presenter note</b>{selectedScenario?.presenter ?? 'This stored change retains its controlled history.'}</p><button data-walkthrough="reset-workspace" disabled={busy} onClick={() => void reset()}>Reset workspace</button></div>
  </section>;
}

function EvaluationPanel({ scenarios }:{ scenarios:ScenarioView[] }) {
  const [scenarioId,setScenarioId] = useState(scenarios[0]?.id ?? 'SCN-001'); const [runId,setRunId] = useState<string|null>(null); const [evaluation,setEvaluation] = useState<EvaluationView|null>(null);
  useEffect(() => { const query = runId ? `?runId=${encodeURIComponent(runId)}` : ''; void api(`/api/evaluations/${scenarioId}${query}`,EvaluationSchema).then((value) => { setEvaluation(value); if (runId && !value.runs.some((run) => run.id === runId)) setRunId(null); }); },[scenarioId,runId]);
  const calculated = evaluation?.calculated; const manual = evaluation?.illustrativeComparisons.manual; const timeSaving = calculated && manual && manual.minutes > 0 ? Math.round((1 - calculated.reviewMinutes / manual.minutes) * 100) : null;
  return <section className="view-content"><div className="page-heading compact"><div><p className="eyebrow teal">Internal validation workflow</p><h1>Evaluation dashboard</h1><p className="lede">This page is separate from the customer compliance workflow. It compares a stored run with a locked provisional human answer key.</p></div><div className="evaluation-selectors"><label className="scenario-select"><span>Scenario</span><select value={scenarioId} onChange={(event) => { setScenarioId(event.target.value);setRunId(null); }}>{scenarios.map((scenario) => <option value={scenario.id} key={scenario.id}>{scenario.number} · {scenario.title}</option>)}</select></label><label className="scenario-select"><span>Stored structured run</span><select value={runId ?? evaluation?.selectedRun?.id ?? ''} onChange={(event) => setRunId(event.target.value)}><option value="">Latest completed run</option>{evaluation?.runs.map((run) => <option value={run.id} key={run.id}>{run.mode} · {new Date(run.createdAt).toLocaleString()}</option>)}</select></label></div></div><div className="evaluation-warning" role="note"><b>Not model-performance evidence.</b> Replay suggestions were authored from the same provisional answer key used here. Use this page to inspect calculation mechanics only until independent QA/RA review is complete.</div>{evaluation ? <>{calculated ? <><div className="gate-grid"><article><p>Critical-impact recall</p><strong>{calculated.criticalRecall}%</strong><span className={calculated.criticalRecall >= evaluation.thresholds.criticalRecall ? 'pass' : 'fail'}>{calculated.criticalRecall >= evaluation.thresholds.criticalRecall ? 'Pass' : 'Below target'} · target {evaluation.thresholds.criticalRecall}%</span></article><article><p>Overall recall</p><strong>{calculated.overallRecall}%</strong><span className={calculated.overallRecall >= evaluation.thresholds.overallRecall ? 'pass' : 'fail'}>{calculated.overallRecall >= evaluation.thresholds.overallRecall ? 'Pass' : 'Below target'} · target {evaluation.thresholds.overallRecall}%</span></article><article><p>Actionable precision</p><strong>{calculated.actionablePrecision}%</strong><span className={calculated.actionablePrecision >= evaluation.thresholds.actionablePrecision ? 'pass' : 'fail'}>{calculated.actionablePrecision >= evaluation.thresholds.actionablePrecision ? 'Pass' : 'Below target'} · target {evaluation.thresholds.actionablePrecision}%</span></article><article><p>Recorded review time</p><strong>{formatReviewDuration(calculated.reviewSeconds,calculated.reviewMinutes)}</strong><span>{timeSaving === null ? 'No comparison' : `${timeSaving}% versus illustrative manual time`}</span></article></div><article className="evaluation-table panel"><div className="panel-heading"><div><p className="eyebrow">Calculated selected-run result</p><h2>{evaluation.scenario.title}</h2></div><span className="tag">Locked provisional ground truth · {evaluation.expectedIds.length} items</span></div><div className="evaluation-run-facts"><span>{calculated.mode === 'replay' ? 'Replay fixture' : 'Live AI'}</span><span>{calculated.reviewed} of {calculated.totalSuggestions} reviewed</span><span>{calculated.accepted} accepted</span><span>{calculated.corrections} action edits</span></div></article></> : <div className="empty-state"><h2>No completed structured run</h2><p>Run a guided replay or live analysis, then record QA decisions. This page does not substitute seeded scores.</p></div>}<article className="evaluation-table panel"><div className="panel-heading"><div><p className="eyebrow">Illustrative comparison fixtures</p><h2>Manual and document-chat values</h2></div><span className="tag">Not calculated from this run</span></div><div className="table-header"><span>Workflow</span><span>Recall</span><span>Precision</span><span>Review time</span></div>{[{ label:'Manual review',metrics:evaluation.illustrativeComparisons.manual },{ label:'Document chat',metrics:evaluation.illustrativeComparisons.chat }].map(({ label,metrics }) => <div className="table-row" key={label}><b>{label}</b><span>{metrics.recall}%</span><span>{metrics.precision}%</span><span>{metrics.minutes} min</span></div>)}</article><div className="evaluation-notes"><article><p className="eyebrow">Ground-truth boundary</p><h3>Provisional and locked in the interface</h3><p>Blue Bridge QA and regulatory specialists must review the answer key before using these measures for a decision.</p></article><article><p className="eyebrow">Calculation boundary</p><h3>QA decisions drive the selected-run result</h3><p>Accepted or edited items count as found. Rejected and pending suggestions do not. Exact update and retest actions determine actionable precision.</p></article></div></> : <Loading />}</section>;
}

export default function Workspace() {
  const [view,setView] = useState<View>('overview'); const [actor,setActor] = useState<Actor>('author'); const [overview,setOverview] = useState<OverviewView|null>(null); const [sources,setSources] = useState<SourceListResponse|null>(null); const [evidence,setEvidence] = useState<EvidenceItem[]>([]); const [documents,setDocuments] = useState<DocumentView[]>([]); const [traceability,setTraceability] = useState<TraceabilityView|null>(null); const [recentChanges,setRecentChanges] = useState<ChangeSummaryView[]>([]); const [selectedEvidence,setSelectedEvidence] = useState<string|null>(null); const [selectedScenario,setSelectedScenario] = useState<ScenarioView|null>(null); const [selectedChangeId,setSelectedChangeId] = useState<string|null>(null); const [walkthroughChange,setWalkthroughChange] = useState<ChangeView|null>(null); const [graphCandidate,setGraphCandidate] = useState<{ key:string;value:CandidateTraceabilityView }|null>(null); const [auditInspected,setAuditInspected] = useState(false); const [baselineCompared,setBaselineCompared] = useState(false); const [coherenceBusy,setCoherenceBusy] = useState(false); const [error,setError] = useState<string|null>(null); const [refreshToken,setRefreshToken] = useState('initial');
  const load = useCallback(async () => { try { const [overviewResult,sourceResult,evidenceResult,documentResult,traceabilityResult,changeResult] = await Promise.all([api('/api/overview',OverviewSchema),api('/api/sources',SourceListResponseSchema),api('/api/evidence',EvidenceListResponseSchema),api('/api/documents',DocumentListResponseSchema),api('/api/traceability',TraceabilitySchema),api('/api/changes?limit=20',ChangeListResponseSchema)]);setOverview(overviewResult);setSources(sourceResult);setEvidence(evidenceResult.evidence);setDocuments(documentResult.documents);setTraceability(traceabilityResult);setRecentChanges(changeResult.changes);setRefreshToken(crypto.randomUUID());setError(null); } catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'Could not load the workspace.'); } },[]);
  useEffect(() => { const timer = window.setTimeout(() => { void load(); },0); return () => window.clearTimeout(timer); },[load]);
  const graphProjectionKey = walkthroughChange && walkthroughChange.relationshipProposals.length > 0 ? `${walkthroughChange.id}:${walkthroughChange.revision}` : null;
  useEffect(() => {
    if (!graphProjectionKey || !walkthroughChange) return;
    let current = true;
    void api(`/api/changes/${walkthroughChange.id}/traceability`,CandidateTraceabilitySchema)
      .then((value) => { if (current) setGraphCandidate({ key:graphProjectionKey,value }); })
      .catch(() => { if (current) setGraphCandidate(null); });
    return () => { current = false; };
  },[graphProjectionKey,walkthroughChange]);
  const currentGraphCandidate = graphCandidate?.key === graphProjectionKey ? graphCandidate.value : null;
  const navigate = useCallback((next:View) => { setView(next);window.scrollTo({ top:0,behavior:'smooth' }); },[]);
  const openIssue = useCallback((itemId:string) => { setSelectedEvidence(itemId);navigate('evidence'); },[navigate]);
  const openChange = useCallback((summary:ChangeSummaryView|null) => { setSelectedChangeId(summary?.id ?? null);setSelectedScenario(summary?.scenarioId ? overview?.scenarios.find((scenario) => scenario.id === summary.scenarioId) ?? null : null); },[overview]);
  const onChangeState = useCallback((change:ChangeView|null) => { setWalkthroughChange(change); },[]);
  const onAuditInspect = useCallback(() => { if (walkthroughChange?.status === 'approved') setAuditInspected(true); },[walkthroughChange?.status]);
  const onBaselineViewed = useCallback((label:string) => { if (overview?.baseline?.label !== 'RR-1.0' && label === 'RR-1.0') setBaselineCompared(true); },[overview?.baseline?.label]);
  const resetWorkspace = useCallback(async () => {
    await api('/api/reset',OverviewSchema,{ method:'POST' });
    setWalkthroughChange(null); setSelectedScenario(null); setSelectedChangeId(null); setSelectedEvidence(null); setActor('author'); setAuditInspected(false); setBaselineCompared(false); navigate('overview');
    await load();
  },[load,navigate]);
  const createRelationshipChange = useCallback(async (proposal:RelationshipProposalDraft) => {
    const anchorItemId = proposal.operation === 'add' ? proposal.sourceId : traceability?.links.find((link) => link.id === proposal.baseRelationshipId)?.sourceId;
    if (!anchorItemId) throw new Error('The relationship anchor could not be resolved.');
    const created = await api('/api/changes',ChangeViewSchema,{ method:'POST',body:JSON.stringify({ kind:'relationship',anchorItemId,title:`${proposal.operation === 'add' ? 'Add' : proposal.operation === 'retype' ? 'Retype' : 'Retire'} controlled relationship`,rationale:proposal.rationale,createdBy:'Alex Morgan · Author',proposal }) });
    setSelectedScenario(null); setSelectedChangeId(created.id); setWalkthroughChange(created); navigate('changes'); await load();
  },[load,navigate,traceability?.links]);
  const runBaselineCheck = async () => { if (!overview?.baseline || actor === 'release_approver') return;setCoherenceBusy(true);setError(null);try { await api('/api/coherence-checks',CoherenceCheckSchema,{ method:'POST',body:JSON.stringify({ scope:{ kind:'baseline',baselineId:overview.baseline.id },actor:demoActor(actor) }) });await load(); } catch (reason:unknown) { setError(reason instanceof Error ? reason.message : 'Could not rerun baseline checks.'); } finally { setCoherenceBusy(false); } };
  const changeBaselineDisposition = async (finding:NonNullable<OverviewView['coherence']>['findings'][number],action:'waived'|'waiver_removed',reason:string) => { if (!overview?.coherence) return;setCoherenceBusy(true);setError(null);try { await api(`/api/coherence-findings/${encodeURIComponent(finding.id)}/dispositions`,CoherenceCheckSchema,{ method:'POST',body:JSON.stringify({ action,runId:overview.coherence.id,fingerprint:finding.fingerprint,actor:'Jamie Chen · QA reviewer',reason }) });await load(); } catch (cause:unknown) { setError(cause instanceof Error ? cause.message : 'Could not record the finding disposition.'); } finally { setCoherenceBusy(false); } };
  const nav:Array<{ label:string;items:Array<{ id:View;label:string;conceptual?:boolean }> }> = [
    { label:'',items:[{ id:'overview',label:'Overview' }] },
    { label:'Inputs',items:[{ id:'sources',label:'Source inbox' },{ id:'connected',label:'Connected systems' }] },
    { label:'Work',items:[{ id:'review',label:'Review centre' },{ id:'changes',label:'Changes' }] },
    { label:'Design controls',items:[{ id:'product-definition',label:'Product definition' },{ id:'requirements',label:'Requirements' },{ id:'components',label:'Components' },{ id:'risk',label:'Risk' },{ id:'verification',label:'Verification' },{ id:'clinical',label:'Clinical & usability' }] },
    { label:'Traceability',items:[{ id:'evidence',label:'Evidence browser' },{ id:'trace-matrix',label:'Matrix' },{ id:'trace-graph',label:'Graph' },{ id:'coverage',label:'Coverage & gaps' }] },
    { label:'Controlled outputs',items:[{ id:'baselines',label:'Baselines' },{ id:'releases',label:'Releases' },{ id:'documents',label:'Documents' },{ id:'design-reviews',label:'Design reviews',conceptual:true }] },
    { label:'Administration',items:[{ id:'integration-setup',label:'Integration setup',conceptual:true },{ id:'analysis-policies',label:'Analysis policies' },{ id:'templates',label:'Templates' },{ id:'people',label:'People & roles',conceptual:true },{ id:'evaluation',label:'Internal evaluation' }] },
  ];
  const lifecycle = [
    { label:'Definition',types:['intended_use','claim','user_need'] },{ label:'Requirements',types:['requirement'] },{ label:'Architecture',types:['component'] },{ label:'Risk',types:['hazard','risk_control'] },{ label:'Verification',types:['test'] },{ label:'Validation',types:['clinical_evidence'] },{ label:'Release',types:['label'] },
  ] as const;

  const req004 = walkthroughChange?.suggestions.find((suggestion) => suggestion.targetId === 'REQ-004');
  const test007 = walkthroughChange?.suggestions.find((suggestion) => suggestion.targetId === 'TEST-007');
  const un004 = walkthroughChange?.suggestions.find((suggestion) => suggestion.targetId === 'UN-004');
  const test007Rejected = walkthroughChange?.audit.some((event) => event.entityId === test007?.id && event.action === 'suggestion_rejected') ?? false;
  const currentUpdates = walkthroughChange?.updates.filter((update) => update.status !== 'superseded' && update.analysisRunId === walkthroughChange.run?.id) ?? [];
  const req004Draft = currentUpdates.find((update) => update.itemId === 'REQ-004');
  const candidateCheckCurrent = Boolean(walkthroughChange?.coherence && !walkthroughChange.coherence.stale);
  const allDecided = walkthroughChange?.suggestions.every((suggestion) => suggestion.decision !== 'pending') ?? false;

  const draftingTarget = actor !== 'author' ? 'actor-chip' : currentUpdates.length === 0 ? 'create-drafts' : !req004Draft?.editedBy ? 'draft-REQ-004' : 'candidate-checks';
  const approvalTarget = walkthroughChange?.status === 'updates_proposed' ? 'submit-candidates' : walkthroughChange?.status === 'qa_review' && actor !== 'qa' ? 'actor-chip' : walkthroughChange?.status === 'qa_review' ? 'approve-baseline' : 'approval-complete';
  const historyTarget = !auditInspected ? 'audit-history' : 'document-baseline';
  const historyView:View = !auditInspected ? 'changes' : 'documents';
  const resetComplete = overview?.baseline?.label === 'RR-1.0' && walkthroughChange === null;

  const walkthroughSteps = useMemo<WalkthroughStep[]>(() => [
    { id:'overview',kind:'explain',view:'overview',target:'overview-boundary',title:'Start with the boundary',body:'RhythmReview is fictional. It contains no patient, client, or submission data, and the simulated roles are not electronic signatures.' },
    { id:'findings',kind:'explain',view:'overview',target:'overview-findings',title:'Separate checks from fixtures',body:'Three findings come from deterministic rules. Three are seeded evaluation fixtures. The workspace deliberately avoids a composite compliance score.' },
    { id:'relationships',kind:'explain',view:'evidence',target:'evidence-relationships',title:'Read the stored relationship direction',body:'REQ-004 groups links by the saved source and target fields. Incoming and outgoing are factual storage directions; QA and RA still need to ratify dependency semantics.' },
    { id:'documents',kind:'explain',view:'documents',target:'document-snapshot',title:'Inspect an immutable snapshot',body:'Each abbreviated document view records its baseline, source versions, approver, and snapshot ID. These views are not submission-ready documents.' },
    { id:'create-analysis',kind:'action',view:'changes',target:walkthroughChange?.run?.mode === 'replay' ? 'suggestion-review' : walkthroughChange ? 'load-replay' : 'create-change',title:'Create the timing change and load replay',body:walkthroughChange?.run?.mode === 'replay' ? 'The locked replay fixture is loaded. It made no external AI call and exists only to demonstrate workflow mechanics.' : walkthroughChange ? 'Load the locked replay fixture. It makes no external AI call and exists only to demonstrate workflow mechanics.' : 'Create the human-authored proposal to extend the controlled result time from 30 to 60 seconds.',complete:walkthroughChange?.scenarioId === 'SCN-002' && walkthroughChange.run?.mode === 'replay',waiting:walkthroughChange ? 'Choose “Load replay fixture”.' : 'Choose “Create controlled change”.' },
    { id:'origins',kind:'explain',view:'changes',target:'suggestion-review',title:'Compare trace paths with semantic candidates',body:'Confirmed graph paths reproduce stored links. Unlinked semantic candidates are clearly separated and never pretend that a relationship exists.' },
    { id:'qa-role',kind:'action',view:'changes',target:'actor-chip',title:'Hand control to QA',body:'The author cannot decide impact scope or approve a baseline. Switch to Jamie Chen, the simulated QA reviewer.',complete:actor === 'qa',waiting:'Use the role control in the header.' },
    { id:'accept-anchor',kind:'action',view:'changes',target:'suggestion-REQ-004',title:'Accept the changed requirement',body:'Accept REQ-004 into scope and record a specific reason. This changes the controlled scope only; it does not edit approved evidence.',complete:req004?.decision === 'accepted',waiting:'Accept REQ-004 and record the QA reason.' },
    { id:'reject-revise',kind:'action',view:'changes',target:'suggestion-TEST-007',title:'Prove that QA decisions retain history',body:'Reject TEST-007 once, then revise the decision to accept it. The final scope is complete and the audit history preserves both decisions.',complete:test007?.decision === 'accepted' && test007Rejected,waiting:test007Rejected ? 'Revise TEST-007 to accepted.' : 'Reject TEST-007 first, with a reason.' },
    { id:'edit-action',kind:'action',view:'changes',target:'suggestion-UN-004',title:'Correct the proposed action',body:'Accept UN-004 with an edited action of “update”. The saved replay action remains unchanged while the human correction becomes effective.',complete:un004?.decision === 'edited' && un004.effectiveAction === 'update',waiting:'Choose “Edit action”, set the replacement to “update”, and record why.' },
    { id:'guided-completion',kind:'action',view:'changes',target:allDecided ? 'suggestion-review' : 'guided-completion',title:'Complete the remaining saved review',body:'The helper fills only pending decisions and labels every result as a guided replay fixture in the audit record.',complete:allDecided,waiting:'Choose “Apply remaining fixture decisions”.' },
    { id:'draft-and-check',kind:'action',view:'changes',target:draftingTarget,title:'Author the candidate and rerun checks',body:actor !== 'author' ? 'Switch back to Alex Morgan before creating candidate evidence.' : currentUpdates.length === 0 ? 'Create the curated replay drafts. They remain separate from approved evidence.' : !req004Draft?.editedBy ? 'Edit the REQ-004 candidate text and save a reason. The original draft remains immutable.' : 'Rerun the projected candidate checks after the author edit so the displayed findings are current.',complete:currentUpdates.length > 0 && Boolean(req004Draft?.editedBy) && candidateCheckCurrent,waiting:actor !== 'author' ? 'Switch to the Author role.' : currentUpdates.length === 0 ? 'Choose “Create candidate drafts”.' : !req004Draft?.editedBy ? 'Edit and save the REQ-004 candidate with a reason.' : 'Choose “Rerun checks”.' },
    { id:'submit-approve',kind:'action',view:'changes',target:approvalTarget,title:'Submit and make the separate QA decision',body:walkthroughChange?.status === 'updates_proposed' ? 'Send the retained candidate versions to QA. RR-1.0 remains approved during this handoff.' : walkthroughChange?.status === 'qa_review' && actor !== 'qa' ? 'Switch to Jamie Chen for the separate baseline decision.' : walkthroughChange?.status === 'qa_review' ? 'Approve the candidate as RR-1.1. The old baseline remains available as immutable history.' : 'RR-1.1 is approved and the stored change is now read-only.',complete:walkthroughChange?.status === 'approved',waiting:walkthroughChange?.status === 'updates_proposed' ? 'Send retained candidate versions to QA.' : walkthroughChange?.status === 'qa_review' && actor !== 'qa' ? 'Switch to the QA reviewer.' : 'Approve the new immutable baseline.' },
    { id:'history',kind:'action',view:historyView,target:historyTarget,title:'Inspect the evidence trail',body:!auditInspected ? 'Open an audit event and inspect its actor, reason, references, and old and new values.' : 'Open RR-1.0 in the document baseline selector. Its snapshot and source versions remain available after RR-1.1 approval.',complete:auditInspected && baselineCompared,waiting:!auditInspected ? 'Expand any audit event.' : 'Select RR-1.0 from the approved baseline control.' },
    { id:'reset',kind:'action',view:resetComplete ? 'overview' : 'changes',target:resetComplete ? 'overview-boundary' : 'reset-workspace',title:'Return to the known starting point',body:resetComplete ? 'The workspace is back on RR-1.0 and is ready for the next demonstration.' : 'Reset removes the demonstration workflow and restores RR-1.0. It does not rebuild or replace the controlled seed tables.',complete:resetComplete,waiting:'Choose “Reset workspace”.' },
  ],[actor,allDecided,auditInspected,baselineCompared,candidateCheckCurrent,currentUpdates.length,draftingTarget,historyTarget,historyView,approvalTarget,req004?.decision,req004Draft?.editedBy,resetComplete,test007?.decision,test007Rejected,un004?.decision,un004?.effectiveAction,walkthroughChange]);

  const onWalkthroughStepEnter = useCallback((stepId:string) => {
    if (stepId === 'overview' && overview?.baseline?.label === 'RR-1.0') { setAuditInspected(false);setBaselineCompared(false); }
    if (stepId === 'relationships') setSelectedEvidence('REQ-004');
    if (stepId === 'create-analysis' && !walkthroughChange && overview) {
      const timing = overview.scenarios.find((scenario) => scenario.id === 'SCN-002') ?? null;
      setSelectedScenario(timing); setSelectedChangeId(null);
    }
  },[overview,walkthroughChange]);

  if ((!overview || !sources) && !error) return <Loading />;
  if (!overview || !sources) return <div className="fatal-state"><h1>Workspace unavailable</h1><p>{error}</p><button onClick={() => void load()}>Try again</button></div>;

  return <main className="app-shell">
    <header className="topbar"><div className="brand-lockup"><div className="brand-mark" aria-hidden="true">BB</div><div><p className="eyebrow">Blue Bridge</p><p className="brand-name">Evidence workspace</p></div></div><div className="workspace-selectors"><label><span>Client</span><select aria-label="Client"><option>Northstar Health</option></select></label><label><span>Product</span><select aria-label="Product"><option>RhythmReview</option></select></label></div><label className="global-search"><span className="sr-only">Search workspace</span><input placeholder="Search evidence, sources, releases…" /></label><div className="baseline-pill"><span className="status-dot" />{overview.baseline?.label ?? 'Working state'} · {overview.baseline?.status ?? 'unbaselined'}</div><button className="review-count" onClick={() => navigate('review')}><b>{sources.reviewCount}</b><span>review tasks</span></button><button className="actor-chip" data-walkthrough="actor-chip" onClick={() => setActor(actor === 'author' ? 'qa' : actor === 'qa' ? 'release_approver' : 'author')} aria-label="Switch demo role"><span className="avatar">{DEMO_ACTORS[actor].initials}</span><span><b>{DEMO_ACTORS[actor].name}</b><small>{DEMO_ACTORS[actor].title} · switch</small></span></button></header>
    <div className="lifecycle-strip" aria-label="Product lifecycle">{lifecycle.map((stage) => { const count = evidence.filter((item) => (stage.types as readonly string[]).includes(item.type)).length; const active = (stage.label === 'Definition' && ['sources','product-definition'].includes(view)) || stage.label.toLowerCase() === view; return <button className={active ? 'active' : ''} key={stage.label} onClick={() => navigate(stage.label === 'Definition' ? 'product-definition' : stage.label === 'Architecture' ? 'components' : stage.label === 'Validation' ? 'clinical' : stage.label === 'Release' ? 'releases' : stage.label.toLowerCase() as View)}><span>{stage.label}</span><b>{count}</b><small>{stage.label === 'Release' ? 'readiness record' : `${count} approved`}</small></button>; })}</div>
    <div className="layout"><aside className="sidebar" aria-label="Workspace navigation"><nav>{nav.map((group) => <div className="nav-group" key={group.label || 'primary'}>{group.label && <p>{group.label}</p>}{group.items.map((item) => <button className={`nav-item ${view === item.id ? 'active' : ''}`} onClick={() => navigate(item.id)} key={item.id}><span>{item.label}</span>{item.conceptual && <em>Concept</em>}</button>)}</div>)}</nav><div><GuidedWalkthrough steps={walkthroughSteps} onNavigate={navigate} onStepEnter={onWalkthroughStepEnter} onResetWorkspace={resetWorkspace} /><div className="sidebar-note"><p className="eyebrow">Prototype boundary</p><p>Decision support only. AI and replay fixtures cannot approve evidence or baselines.</p></div></div></aside><div className="content-area">{error && <div className="error-banner">{error}</div>}
      {view === 'overview' && <><OverviewPanel overview={overview} sources={sources} onNavigate={navigate} />{overview.coherence && <CoherenceWorkspace title="Approved baseline finding dispositions" check={overview.coherence} actor={actor} busy={coherenceBusy} onRun={() => void runBaselineCheck()} onDisposition={(finding,action,reason) => void changeBaselineDisposition(finding,action,reason)} onOpenEvidence={openIssue} />}</>}
      {view === 'sources' && <SourceWorkspace mode="inbox" actor={actor} workspace={sources} onWorkspaceChange={(next) => { setSources(next);void load(); }} />}
      {view === 'connected' && <ConnectedSystemsPanel />}
      {view === 'review' && <SourceWorkspace mode="review" actor={actor} workspace={sources} onWorkspaceChange={(next) => { setSources(next);void load(); }} />}
      {view === 'product-definition' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} initialType="user_need" title="Product definition" description="Inspect intended use, claims, and reviewed user needs in the active baseline." />}
      {view === 'requirements' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} initialType="requirement" title="Requirements hierarchy" description="Product, system, and subsystem requirements remain independently reviewable." />}
      {view === 'components' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} initialType="component" title="Components" description="Controlled architecture components; future repository observations remain separate inputs." />}
      {view === 'risk' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} initialType="hazard" title="Risk evidence" description="Existing hazards and controls are visible; AI-assisted risk generation is deferred." />}
      {view === 'verification' && <VerificationWorkspacePanel actor={actor} onOpenChange={(changeId) => { setSelectedScenario(null);setSelectedChangeId(changeId);navigate('changes'); }} onWorkspaceRefresh={load} />}
      {view === 'clinical' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} initialType="clinical_evidence" title="Clinical & usability" description="Clinical and usability evidence in the active approved baseline." />}
      {view === 'evidence' && <EvidencePanel key={view} evidence={evidence} selectedId={selectedEvidence} onSelect={setSelectedEvidence} />}
      {view === 'baselines' && <BaselineWorkspace workspace={sources} actor={actor} currentBaseline={overview.baseline?.label ?? 'No approved baseline'} onWorkspaceChange={(next) => { setSources(next);void load(); }} />}
      {view === 'releases' && <ReleaseWorkspacePanel actor={actor} baseline={overview.baseline ? { id:overview.baseline.id,label:overview.baseline.label } : null} onWorkspaceRefresh={load} onNavigate={navigate} />}
      {view === 'documents' && <ControlledDocumentsPanel documents={documents} refreshToken={refreshToken} onBaselineViewed={onBaselineViewed} actor={actor} baseline={overview.baseline ? { id:overview.baseline.id,label:overview.baseline.label } : null} />}
      {view === 'changes' && <ChangePanel overview={overview} evidence={evidence} recentChanges={recentChanges} openChangeId={selectedChangeId} actor={actor} selectedScenario={selectedScenario} setSelectedScenario={setSelectedScenario} onOpenChange={openChange} onWorkspaceRefresh={load} onOpenEvidence={openIssue} onChangeState={onChangeState} onResetWorkspace={resetWorkspace} onAuditInspect={onAuditInspect} />}
      {view === 'analysis-policies' && <ConceptualPanel title="Analysis policies" description="The implemented policies and contracts used by each recorded processing run." items={['source-context-v3: required and advisory questions with exact source spans and explicit-decision suppression','user-needs-v2: solution-independent needs with typed provenance','requirements-v2: atomic shall statements with explicit values and accepted parent needs','impact-v6: exhaustive bounded semantic classification with controlled categories and enforceable type-appropriate actions']} />}
      {view === 'trace-matrix' && traceability && <TraceabilityWorkspace mode="matrix" traceability={traceability} evidence={evidence} actor={actor} onOpenEvidence={openIssue} onCreateRelationship={createRelationshipChange} />}
      {view === 'trace-graph' && traceability && <TraceabilityGraph traceability={traceability} candidate={currentGraphCandidate} change={walkthroughChange} selectedId={selectedEvidence} onSelect={setSelectedEvidence} onOpenEvidence={openIssue} />}
      {view === 'coverage' && traceability && <TraceabilityWorkspace mode="coverage" traceability={traceability} evidence={evidence} actor={actor} onOpenEvidence={openIssue} onCreateRelationship={createRelationshipChange} />}
      {view === 'design-reviews' && <ConceptualPanel title="Design reviews" description="Formal review records and deliverable gates are planned here." items={['Review scope and participants','Findings and dispositions','Immutable review record']} />}
      {view === 'integration-setup' && <ConceptualPanel title="Integration setup" description="Credentials and external-field mappings are deliberately separate from operational connection status." items={['Repository credentials and mappings','Jira project and hierarchy mapping','CI observation configuration']} />}
      {view === 'templates' && <TemplateWorkspace actor={actor} onWorkspaceRefresh={load} />}
      {view === 'people' && <ConceptualPanel title="People & roles" description="Discipline and permission configuration for routing and separate decisions." items={['Authors, reviewers, and approvers','Clinical, engineering, test, QA and product disciplines','Permission and ownership rules']} />}
      {view === 'evaluation' && <EvaluationPanel scenarios={overview.scenarios} />}
    </div></div>
  </main>;
}
